head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > M > appendXmlNodes]<br/>트리 아이템 객체와 XML 객체를 사용하여 특정 트리 아이템에 자식 아이템을 추가합니다.",
    "validation" : [
        "renderType=table 이고 트리 아이템이 ItemSet 으로 정의된 경우에 동작합니다.",
        "parentNode(필수) 파라미터로 자식 아이템을 추가 하려는 트리 아이템을 객체로 설정합니다.",
        "xmlArray(필수) 자식 아이템으로 추가할 데이터를 XML 객체의 배열로 설정합니다.",
        "아이템에 해당하는 XML 객체는 'map' 태그로 정의해야 합니다.",
        "parentNode 파라미터에 해당하는 트리 아이템의 마지막 자식으로 추가됩니다.",
        "Depth(단계) 값이 parentNode 파라미터에 해당하는 트리 아이템보다 작은 경우 자동으로 수정됩니다.",
        "인덱스는 전체 트리 아이템의 마지막 인덱스부터 순서대로 설정됩니다.",
        "트리 아이템이 ItemSet 으로 정의된 경우 DataCollection 에 추가된 트리 아이템이 반영되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {            
        showCheckbox : true,  
        dynamicAppend : true,  
    }

    let cList = $c.gcm.createCList(properties);    
    let eList = $c.gcm.createEList(["onclick"]);

    $c.gcm.createLabel('label="자식 아이템을 추가할 아이템을 클릭하여 확인"', '', 'label1')    ;
    $c.gcm.createBasicTreeView(cList, eList);
}



scwin.getDataList = function () {
    let rtn = gdl_treeview.getRowCount();

    wf_body_bottom.getObj("scwin").setReturnValue("getRowCount : " + rtn);
}



scwin.getText = function () {
    let rtn = target1.render.textContent;

    wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);
}



scwin.button1_onclick = function (e) {
    //3. Script 영역에서 TreeView에 선택 된 노드 하위로 appendXmlNodes API를 호출하여 노드(항목)추가하기
    //3.1 TreeView에서 선택 된 노드 얻기
    var tmpPNode = target1.getSelectedNode();

    //3.2 선택 된 노드가 없는 경우 alert. 
    if(!tmpPNode){
        wf_body_bottom.getObj("scwin").setReturnValue("TreeView의 항목(노드)를 선택하세요");
        return;
    }

    //3.3 추가할 XML 문자열 생성
    var tmpStr = "<list>";
    tmpStr += "<map><depth>2</depth><label>메뉴1-1</label><value>menu1-1</value></map>";
    tmpStr += "<map><depth>2</depth><label>메뉴1-2</label><value>menu1-2</value></map>";
    tmpStr += "</list>";

    //3.4 XML 생성
    var tmpDoc = WebSquare.xml.parse(tmpStr);

    //3.5 appendXmlNodes에 사용할 파라메터 (XML Array) 생성
    var tmpDocArr = WebSquare.xml.findNodes(tmpDoc,"list/map"); 

    //3.6 선택 된 노드에 추가.
    target1.appendXmlNodes( tmpPNode , tmpDocArr );	

    scwin.getText();
    scwin.getDataList();    
};



scwin.target1_onclick = function () {
	scwin.button1_onclick();
};
